148		// 快照对应本次申请成交的合约 A。
149		if !rec.QuoteValid || rec.QuoteSeq != 1 || rec.QuoteMoment != 10 || rec.QuotePrice != 10 {
150			t.Fatalf("拒绝记录的报价快照必须取自合约 A: %+v", rec)
151		}
152		if !rec.MaxPositionValid || rec.MaxPosition != 100 {
153			t.Fatalf("拒绝记录的最大持仓量快照必须取自合约 A: %+v", rec)
154		}
155	
156		// 现金余额、可用现金、买单现金占用、持仓以及两张订单的累计成交量、剩余量、
157		// 状态全部与冲突提交前一致。
158		after := snapshotTradeIDConflictLedger(e, order1, order2, "A", "A")
159		if after != before {
160			t.Fatalf("编号冲突不得改变任何资金、持仓或订单状态:\n之前 %+v\n之后 %+v", before, after)
161		}
162		if o, _ := e.Order(order2); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 10 {
163			t.Fatalf("第二张订单不能被当作已经成交: %+v", o)
164		}
165	
166		// 原有接受记录与成交记录原样保留，只在末尾追加了那一条拒绝记录。
167		recs := e.Records()
168		for i, want := range recordsBefore {
169			if !reflect.DeepEqual(recs[i], want) {
170				t.Fatalf("第 %d 条原有记录被改写:\nwant %+v\ngot  %+v", i, want, recs[i])
171			}
172		}
173	
174		// 冲突后重新提交最初成功入账的完整回报：仍返回第一次成交结果（第一次入账时
175		// 的累计成交量 4、剩余量 6、部分成交状态），不新增记录也不再次记账。
176		again, err := e.Fill(first)
177		if err != nil {
178			t.Fatalf("原成交完整重放不应报错: %v", err)
179		}
180		if again != res1 {
181			t.Fatalf("原成交重放必须返回第一次结果: want %+v got %+v", res1, again)
182		}
183		if len(e.Records()) != recsBefore+1 {
184			t.Fatalf("原成交重放不得新增记录，实际 %d 条", len(e.Records()))
185		}
186		if got := snapshotTradeIDConflictLedger(e, order1, order2, "A", "A"); got != before {
187			t.Fatalf("原成交重放不得再次改变资金、持仓或订单: %+v", got)
188		}
189	
190		// 第二张订单换用尚未使用的正成交编号 2，提交原先被拒绝的价格 9 与数量 4：
191		// 按实际金额 36 扣现金，按其限价 10 释放 4 份占用，持仓增加 4。
192		res2, err := e.Fill(Trade{TradeID: 2, OrderID: order2, Symbol: "A", Side: Buy, Price: 9, Qty: 4})
193		if err != nil {
194			t.Fatalf("换新编号后第二张订单应正常成交: %v", err)
195		}
196		if res2.TradeID != 2 || res2.OrderID != order2 || res2.Price != 9 || res2.Qty != 4 ||
197			res2.Filled != 4 || res2.Remaining != 6 || res2.Status != StatusPartial {
198			t.Fatalf("第二张订单成交结果错误: %+v", res2)
199		}
200		if e.Cash() != 9928 || e.ReservedCash() != 120 || e.AvailableCash() != 9808 || e.Position("A") != 8 {
201			t.Fatalf("第二张订单成交后账务错误: cash=%d reserved=%d available=%d pos=%d",
202				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
203		}
204		if o, _ := e.Order(order1); o.Filled != 4 || o.Remaining() != 6 || o.Status != StatusPartial {
205			t.Fatalf("第一张订单必须保持原状: %+v", o)
206		}
207		if o, _ := e.Order(order2); o.Filled != 4 || o.Remaining() != 6 || o.Status != StatusPartial {
208			t.Fatalf("第二张订单应累计成交 4、剩余 6、部分成交: %+v", o)
209		}
210	
211		// 只在拒绝记录之后新增一条成交记录；拒绝记录与此前各条记录都原样保留。
212		recs = e.Records()
213		if len(recs) != recsBefore+2 {
214			t.Fatalf("换新编号成交后应只比冲突前多两条记录（拒绝+成交），实际 %d 条",
215				len(recs)-recsBefore)
216		}
217		if recs[recsBefore].Kind != RecordRejected || recs[recsBefore].TradeID != 1 ||
218			recs[recsBefore].OrderID != order2 {
219			t.Fatalf("编号冲突拒绝记录必须保留: %+v", recs[recsBefore])
220		}
221		fill2 := recs[recsBefore+1]
222		if fill2.Kind != RecordFilled || fill2.TradeID != 2 || fill2.OrderID != order2 ||
223			fill2.Symbol != "A" || fill2.Side != Buy || fill2.TradePrice != 9 ||
224			fill2.Qty != 4 || fill2.Filled != 4 || fill2.Remaining != 6 {
225			t.Fatalf("第二张订单的新成交记录错误: %+v", fill2)
226		}
227	}
228	
229	// TestFillTradeIDReuseByAnotherBuyDifferentSymbol 覆盖不同合约的两张买单，确认
230	// 成交编号唯一性作用于整个账户而不是各合约分别计算：A 合约买单的已成交编号
231	// 不能被 B 合约的有效买单借用。冲突拒绝记录的报价与最大持仓量快照必须取自
232	// 本次申请的 B 合约，不能错用最初成交的 A 合约。
233	func TestFillTradeIDReuseByAnotherBuyDifferentSymbol(t *testing.T) {
234		e, _ := NewEngine(10000)
235		mustSetMax(t, e, "A", 100)
236		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
237		mustSetMax(t, e, "B", 50)
238		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 20, Price: 9}, 1)
239	
240		orderA := mustBuy(t, e, "A", 10, 10) // ID=1，A 合约
241		orderB := mustBuy(t, e, "B", 10, 9)  // ID=2，B 合约的有效买单
242	
243		// A 合约买单先以价格 9 部分成交 4 份：现金 9964，买单占用 190-40=150，
244		// 持仓 A=4、B=0。
245		first := Trade{TradeID: 1, OrderID: orderA, Symbol: "A", Side: Buy, Price: 9, Qty: 4}
246		res1, err := e.Fill(first)
247		if err != nil {
248			t.Fatalf("A 合约买单部分成交应成功: %v", err)
249		}
250		if res1.Filled != 4 || res1.Remaining != 6 || res1.Status != StatusPartial {
251			t.Fatalf("第一次成交结果错误: %+v", res1)
252		}
253		if e.Cash() != 9964 || e.ReservedCash() != 150 || e.AvailableCash() != 9814 ||
254			e.Position("A") != 4 || e.Position("B") != 0 {
255			t.Fatalf("前置账务错误: cash=%d reserved=%d available=%d posA=%d posB=%d",
256				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Position("B"))
257		}
258	
259		recsBefore := len(e.Records())
260		recordsBefore := e.Records()
261		before := snapshotTradeIDConflictLedger(e, orderA, orderB, "A", "B")
262	
263		// B 合约订单本身完全可成交（价格 9 等于限价 9、数量 4 不超过剩余 10、订单
264		// 待成交），提交与第一笔成交完全相同的价格和数量，仅成交编号撞号：跨合约
265		// 借用编号必须拒绝，证明唯一性按整个账户计算。
266		conflict := Trade{TradeID: 1, OrderID: orderB, Symbol: "B", Side: Buy, Price: 9, Qty: 4}
267		rec := assertTradeIDReuseRejected(t, e, conflict, first, recsBefore)
268	
269		// 拒绝记录指向 B（本次申请成交的合约），原因里的原成交指向 A。
270		if rec.Symbol != "B" {
271			t.Fatalf("拒绝记录必须保存本次提交的合约 B，实际 %q", rec.Symbol)
272		}
273		if !rec.QuoteValid || rec.QuoteSeq != 1 || rec.QuoteMoment != 20 || rec.QuotePrice != 9 {
274			t.Fatalf("拒绝记录的报价快照必须取自本次申请合约 B: %+v", rec)
275		}
276		if !rec.MaxPositionValid || rec.MaxPosition != 50 {
277			t.Fatalf("拒绝记录的最大持仓量快照必须取自本次申请合约 B: %+v", rec)
278		}
279		// 明确不能错用最初成交合约 A（报价 10、限额 100、时刻 10）的快照。
280		if rec.QuotePrice == 10 || rec.QuoteMoment == 10 || rec.MaxPosition == 100 {
281			t.Fatalf("拒绝记录不得错用最初成交合约 A 的报价/限额快照: %+v", rec)
282		}
283	
284		after := snapshotTradeIDConflictLedger(e, orderA, orderB, "A", "B")
285		if after != before {
286			t.Fatalf("跨合约编号冲突不得改变任何资金、持仓或订单状态:\n之前 %+v\n之后 %+v", before, after)
287		}
288		if o, _ := e.Order(orderB); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 10 {
289			t.Fatalf("B 合约订单不能被当作已经成交: %+v", o)
290		}
291		if o, _ := e.Order(orderA); o.Status != StatusPartial || o.Filled != 4 || o.Remaining() != 6 {
292			t.Fatalf("A 合约订单已入账部分不能回退: %+v", o)
293		}
294	
295		recs := e.Records()
296		for i, want := range recordsBefore {
297			if !reflect.DeepEqual(recs[i], want) {
298				t.Fatalf("第 %d 条原有记录被改写:\nwant %+v\ngot  %+v", i, want, recs[i])
299			}
300		}
301	
302		// 原成交（A 合约）完整重放：返回第一次结果，不新增记录、不再次记账。
303		again, err := e.Fill(first)
304		if err != nil {
305			t.Fatalf("原成交完整重放不应报错: %v", err)
306		}
307		if again != res1 {
308			t.Fatalf("原成交重放必须返回第一次结果: want %+v got %+v", res1, again)
309		}
310		if len(e.Records()) != recsBefore+1 {
311			t.Fatalf("原成交重放不得新增记录，实际 %d 条", len(e.Records()))
312		}
313	
314		// B 合约订单换用新编号 2 提交原价格 9、原数量 4：按 9×4=36 扣现金并按其
315		// 限价 9 释放 36 占用，B 持仓增加 4；A 合约持仓与第一张订单保持原状。
316		resB, err := e.Fill(Trade{TradeID: 2, OrderID: orderB, Symbol: "B", Side: Buy, Price: 9, Qty: 4})
317		if err != nil {
318			t.Fatalf("B 合约订单换新编号后应正常成交: %v", err)
319		}
320		if resB.TradeID != 2 || resB.OrderID != orderB || resB.Filled != 4 ||
321			resB.Remaining != 6 || resB.Status != StatusPartial {
322			t.Fatalf("B 合约订单成交结果错误: %+v", resB)
323		}
324		if e.Cash() != 9928 || e.ReservedCash() != 114 || e.AvailableCash() != 9814 ||
325			e.Position("A") != 4 || e.Position("B") != 4 {
326			t.Fatalf("B 合约订单成交后账务错误: cash=%d reserved=%d available=%d posA=%d posB=%d",
327				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Position("B"))
328		}
329		if o, _ := e.Order(orderA); o.Filled != 4 || o.Remaining() != 6 || o.Status != StatusPartial {
330			t.Fatalf("A 合约第一张订单必须保持原状: %+v", o)
331		}
332		if o, _ := e.Order(orderB); o.Filled != 4 || o.Remaining() != 6 || o.Status != StatusPartial {
333			t.Fatalf("B 合约订单应累计成交 4、剩余 6、部分成交: %+v", o)
334		}
335	
336		recs = e.Records()
337		if len(recs) != recsBefore+2 {
338			t.Fatalf("换新编号成交后应只比冲突前多两条记录（拒绝+成交），实际 %d 条",
339				len(recs)-recsBefore)
340		}
341		if recs[recsBefore].Kind != RecordRejected || recs[recsBefore].TradeID != 1 ||
342			recs[recsBefore].OrderID != orderB || recs[recsBefore].Symbol != "B" {
343			t.Fatalf("跨合约编号冲突拒绝记录必须保留: %+v", recs[recsBefore])
344		}
345		fillB := recs[recsBefore+1]
346		if fillB.Kind != RecordFilled || fillB.TradeID != 2 || fillB.OrderID != orderB ||
347			fillB.Symbol != "B" || fillB.TradePrice != 9 || fillB.Qty != 4 ||
348			fillB.Filled != 4 || fillB.Remaining != 6 {
349			t.Fatalf("B 合约订单的新成交记录错误: %+v", fillB)
350		}
351	}
