6	)
7	
8	// 本文件为“成交回报必须与订单编号所确定的委托一致”补充回归保障：
9	// 订单由编号确定，回报中的合约与买卖方向都必须和该笔委托一致才允许入账。
10	// 合约写错（订单属于 A，回报写成另一个已有报价、限额、持仓与有效订单的 B）
11	// 或方向写反（买单收到卖出回报、卖单收到买入回报）都必须整笔拒绝：返回错误
12	// 与零值成交结果，只新增一条说明具体不一致原因的拒绝记录（保留本次提交的
13	// 订单编号、成交编号、合约、方向、价格、数量），资金、持仓、可卖数量与所有
14	// 订单的状态、累计成交量、剩余量及各项占用都保持提交前的值；绝不能转而寻找
15	// 所填合约的订单入账，也不能按回报方向调整原订单。被拒绝的成交不占用编号，
16	// 把合约和方向改回该订单的实际值后，同一编号可按普通成交成功入账。
17	
18	// assertFillMismatchRejected 校验一次不一致回报被拒绝后的全部不变量：
19	// 返回错误与零值结果、错误与记录都说明具体不一致原因、只新增一条拒绝记录，
20	// 且记录完整保留本次提交的订单编号、成交编号、合约、方向、价格与数量。
21	func assertFillMismatchRejected(t *testing.T, e *Engine, tr Trade, recsBefore int, wantReason ...string) {
22		t.Helper()
23		res, err := e.Fill(tr)
24		if err == nil {
25			t.Fatalf("不一致的成交 %+v 必须报错", tr)
26		}
27		for _, s := range wantReason {
28			if !strings.Contains(err.Error(), s) {
29				t.Fatalf("错误 %q 应包含 %q", err.Error(), s)
30			}
31		}
32		if res != (FillResult{}) {
33			t.Fatalf("不一致拒绝必须返回零值成交结果，实际 %+v", res)
34		}
35		recs := e.Records()
36		if len(recs) != recsBefore+1 {
37			t.Fatalf("不一致拒绝只能新增一条记录，实际新增 %d 条", len(recs)-recsBefore)
38		}
39		rec := recs[len(recs)-1]
40		if rec.Kind != RecordRejected {
41			t.Fatalf("新增记录必须是拒绝记录: %+v", rec)
42		}
43		if rec.OrderID != tr.OrderID || rec.TradeID != tr.TradeID || rec.Symbol != tr.Symbol ||
44			rec.Side != tr.Side || rec.TradePrice != tr.Price || rec.Qty != tr.Qty {
45			t.Fatalf("拒绝记录必须保留本次提交的订单/成交编号、合约、方向、价格、数量: %+v", rec)
46		}
47		for _, s := range wantReason {
48			if !strings.Contains(rec.Reason, s) {
49				t.Fatalf("拒绝原因 %q 应包含 %q", rec.Reason, s)
50			}
51		}
52	}
53	
54	// TestFillSymbolMismatchRejectedThenCorrected 覆盖合约不一致：目标订单属于 A，
55	// 已有部分成交；B 是另一个已有报价、限额、持仓与有效订单的合约且资金充足。
56	// 把回报合约写成 B 必须拒绝，不能转而寻找 B 的订单入账；随后用同一成交编号
57	// 改回 A 后按普通成交入账：只扣除本次成交金额、新增对应持仓、释放对应限价
58	// 占用，先前拒绝记录保留，B 合约与其他订单的账务不受影响。
59	func TestFillSymbolMismatchRejectedThenCorrected(t *testing.T) {
60		e, _ := NewEngine(1000)
61		mustSetMax(t, e, "A", 100)
62		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
63		mustSetMax(t, e, "B", 100)
64		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 11, Price: 5}, 1)
65	
66		// B 已有持仓 10 与一笔有效卖单（占用可卖 4），资金充足。
67		bBuy := mustBuy(t, e, "B", 10, 5)
68		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bBuy, Symbol: "B", Side: Buy, Price: 5, Qty: 10}); err != nil {
69			t.Fatal(err)
70		}
71		bSell := mustSell(t, e, "B", 4, 5)
72	
73		// 目标买单：A 总量 10、限价 10；另有一笔有效买单用于验证不受影响。
74		aBuy := mustBuy(t, e, "A", 10, 10)
75		aBuy2 := mustBuy(t, e, "A", 2, 10)
76	
77		// 先以价格 9 成交 4 份：现金 1000-50-36=914，占用 120-40=80，持仓 A=4。
78		if _, err := e.Fill(Trade{TradeID: 2, OrderID: aBuy, Symbol: "A", Side: Buy, Price: 9, Qty: 4}); err != nil {
79			t.Fatal(err)
80		}
81		if e.Cash() != 914 || e.ReservedCash() != 80 || e.AvailableCash() != 834 {
82			t.Fatalf("前置资金状态错误: cash=%d reserved=%d available=%d",
83				e.Cash(), e.ReservedCash(), e.AvailableCash())
84		}
85		if e.Position("A") != 4 || e.Sellable("A") != 4 || e.Position("B") != 10 || e.Sellable("B") != 6 {
86			t.Fatalf("前置持仓状态错误: posA=%d sellableA=%d posB=%d sellableB=%d",
87				e.Position("A"), e.Sellable("A"), e.Position("B"), e.Sellable("B"))
88		}
89	
90		// 订单属于 A，回报却写成 B：即使 B 有有效订单且资金充足也必须拒绝，
91		// 不能转而寻找 B 的订单入账。
92		recsBefore := len(e.Records())
93		assertFillMismatchRejected(t, e,
94			Trade{TradeID: 3, OrderID: aBuy, Symbol: "B", Side: Buy, Price: 10, Qty: 2},
95			recsBefore, "合约", "不一致", "B", "A")
96	
97		// 全部资金、持仓与订单状态保持提交前的值。
98		if e.Cash() != 914 || e.ReservedCash() != 80 || e.AvailableCash() != 834 {
99			t.Fatalf("合约不一致拒绝不得改变资金: cash=%d reserved=%d available=%d",
100				e.Cash(), e.ReservedCash(), e.AvailableCash())
101		}
102		if e.Position("A") != 4 || e.Sellable("A") != 4 || e.Position("B") != 10 || e.Sellable("B") != 6 {
103			t.Fatalf("合约不一致拒绝不得改变两个合约的持仓与可卖: posA=%d sellableA=%d posB=%d sellableB=%d",
104				e.Position("A"), e.Sellable("A"), e.Position("B"), e.Sellable("B"))
105		}
106		if o, _ := e.Order(aBuy); o.Status != StatusPartial || o.Filled != 4 || o.Remaining() != 6 {
107			t.Fatalf("目标订单已入账部分不得回退、剩余占用不得释放: %+v", o)
108		}
109		if o, _ := e.Order(aBuy2); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 2 {
110			t.Fatalf("其他有效买单不得受影响: %+v", o)
111		}
112		if o, _ := e.Order(bSell); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 4 {
113			t.Fatalf("B 合约的有效订单不得被转而入账: %+v", o)
114		}
115	
116		// 同一编号把合约改回 A、其余条件合法：按普通成交成功入账。
117		res, err := e.Fill(Trade{TradeID: 3, OrderID: aBuy, Symbol: "A", Side: Buy, Price: 10, Qty: 2})
118		if err != nil {
119			t.Fatalf("被拒绝的成交编号改回合约会应可复用: %v", err)
120		}
121		if res.TradeID != 3 || res.OrderID != aBuy || res.Price != 10 || res.Qty != 2 ||
122			res.Filled != 6 || res.Remaining != 4 || res.Status != StatusPartial {
123			t.Fatalf("修正后成交结果错误: %+v", res)
124		}
125		// 只扣除 2×10=20 现金，新增 2 份持仓，释放这 2 份对应的限价占用。
126		if e.Cash() != 894 || e.ReservedCash() != 60 || e.AvailableCash() != 834 {
127			t.Fatalf("修正后资金错误: cash=%d reserved=%d available=%d",
128				e.Cash(), e.ReservedCash(), e.AvailableCash())
129		}
130		if e.Position("A") != 6 || e.Sellable("A") != 6 {
131			t.Fatalf("修正后持仓错误: pos=%d sellable=%d", e.Position("A"), e.Sellable("A"))
132		}
133		if o, _ := e.Order(aBuy); o.Status != StatusPartial || o.Filled != 6 || o.Remaining() != 4 {
134			t.Fatalf("订单应累计成交 6、剩余 4: %+v", o)
135		}
136		// B 合约与其他订单的账务不受影响。
137		if e.Position("B") != 10 || e.Sellable("B") != 6 {
138			t.Fatalf("B 合约账务不得受影响: pos=%d sellable=%d", e.Position("B"), e.Sellable("B"))
139		}
140		if o, _ := e.Order(aBuy2); o.Status != StatusPending || o.Remaining() != 2 {
141			t.Fatalf("其他有效买单不得受影响: %+v", o)
142		}
143		if o, _ := e.Order(bSell); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 4 {
144			t.Fatalf("B 合约有效订单不得受影响: %+v", o)
145		}
146	
147		// 先前的拒绝记录保留；修正后只新增一条成交记录。
148		recs := e.Records()
149		if len(recs) != recsBefore+2 {
150			t.Fatalf("修正成交后应只比拒绝前多两条记录（拒绝+成交），实际 %d 条", len(recs)-recsBefore)
151		}
152		rej, fill := recs[recsBefore], recs[recsBefore+1]
153		if rej.Kind != RecordRejected || rej.TradeID != 3 || rej.Symbol != "B" {
154			t.Fatalf("先前拒绝记录必须保留: %+v", rej)
155		}
156		if fill.Kind != RecordFilled || fill.TradeID != 3 || fill.Symbol != "A" || fill.Side != Buy ||
157			fill.TradePrice != 10 || fill.Qty != 2 || fill.Filled != 6 || fill.Remaining != 4 {
158			t.Fatalf("修正后的成交记录错误: %+v", fill)
159		}
160	
161		// 已入账的成交幂等重放：返回原结果，不再新增记录或重复记账。
162		again, err := e.Fill(Trade{TradeID: 3, OrderID: aBuy, Symbol: "A", Side: Buy, Price: 10, Qty: 2})
163		if err != nil || again != res {
164			t.Fatalf("幂等重放应返回原结果: %+v, %v", again, err)
165		}
166		if len(e.Records()) != len(recs) || e.Cash() != 894 || e.Position("A") != 6 {
167			t.Fatalf("幂等重放不得新增记录或重复记账: recs=%d cash=%d pos=%d",
168				len(e.Records()), e.Cash(), e.Position("A"))
169		}
170	}
171	
172	// TestFillSideMismatchRejectedThenCorrected 覆盖方向不一致：买单收到卖出回报、
173	// 卖单收到买入回报都必须拒绝，不能根据回报方向调整原订单；同一编号改回实际
174	// 方向后按普通成交入账。
175	func TestFillSideMismatchRejectedThenCorrected(t *testing.T) {
176		e, _ := NewEngine(1000)
177		mustSetMax(t, e, "A", 100)
178		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
179	
180		b0 := mustBuy(t, e, "A", 10, 10)
181		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b0, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
182			t.Fatal(err)
183		}
184		// 目标买单（待成交）与目标卖单（占用 6 可卖）。
185		aBuy := mustBuy(t, e, "A", 5, 10)
186		aSell := mustSell(t, e, "A", 6, 9)
187	
188		if e.Cash() != 900 || e.ReservedCash() != 50 || e.Position("A") != 10 || e.Sellable("A") != 4 {
189			t.Fatalf("前置状态错误: cash=%d reserved=%d pos=%d sellable=%d",
190				e.Cash(), e.ReservedCash(), e.Position("A"), e.Sellable("A"))
191		}
192	
193		// 买单收到卖出回报：拒绝，不能按回报方向把买单当卖单处理。
194		recsBefore := len(e.Records())
195		assertFillMismatchRejected(t, e,
196			Trade{TradeID: 2, OrderID: aBuy, Symbol: "A", Side: Sell, Price: 10, Qty: 2},
197			recsBefore, "方向", "不一致", "卖出", "买入")
198		// 卖单收到买入回报：同样拒绝。
199		assertFillMismatchRejected(t, e,
200			Trade{TradeID: 3, OrderID: aSell, Symbol: "A", Side: Buy, Price: 10, Qty: 2},
201			recsBefore+1, "方向", "不一致", "买入", "卖出")
202	
203		// 资金、持仓、可卖与两笔订单的方向、状态、剩余量全部保持提交前的值。
204		if e.Cash() != 900 || e.ReservedCash() != 50 || e.AvailableCash() != 850 {
205			t.Fatalf("方向不一致拒绝不得改变资金: cash=%d reserved=%d available=%d",
206				e.Cash(), e.ReservedCash(), e.AvailableCash())
207		}
208		if e.Position("A") != 10 || e.Sellable("A") != 4 {
209			t.Fatalf("方向不一致拒绝不得改变持仓与可卖占用: pos=%d sellable=%d",
210				e.Position("A"), e.Sellable("A"))
211		}
212		if o, _ := e.Order(aBuy); o.Side != Buy || o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 5 {
213			t.Fatalf("买单不得按回报方向调整: %+v", o)
214		}
215		if o, _ := e.Order(aSell); o.Side != Sell || o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 6 {
216			t.Fatalf("卖单不得按回报方向调整: %+v", o)
217		}
218	
219		// 同一编号改回实际方向后按普通成交入账。
220		res, err := e.Fill(Trade{TradeID: 2, OrderID: aBuy, Symbol: "A", Side: Buy, Price: 10, Qty: 2})
221		if err != nil {
222			t.Fatalf("买单修正方向后同编号成交应成功: %v", err)
223		}
224		if res.Filled != 2 || res.Remaining != 3 || res.Status != StatusPartial {
225			t.Fatalf("买单修正后成交结果错误: %+v", res)
226		}
227		if e.Cash() != 880 || e.ReservedCash() != 30 || e.Position("A") != 12 {
228			t.Fatalf("买单修正后账务错误: cash=%d reserved=%d pos=%d",
229				e.Cash(), e.ReservedCash(), e.Position("A"))
230		}
231	
232		res, err = e.Fill(Trade{TradeID: 3, OrderID: aSell, Symbol: "A", Side: Sell, Price: 9, Qty: 2})
233		if err != nil {
234			t.Fatalf("卖单修正方向后同编号成交应成功: %v", err)
235		}
236		if res.Filled != 2 || res.Remaining != 4 || res.Status != StatusPartial {
237			t.Fatalf("卖单修正后成交结果错误: %+v", res)
238		}
239		// 卖出按实际所得 2×9=18 增加现金、减少持仓并释放相应可卖占用。
240		if e.Cash() != 898 || e.Position("A") != 10 || e.Sellable("A") != 6 {
241			t.Fatalf("卖单修正后账务错误: cash=%d pos=%d sellable=%d",
242				e.Cash(), e.Position("A"), e.Sellable("A"))
243		}
244	
245		// 两条方向不一致的拒绝记录都保留。
246		recs := e.Records()
247		for i, tr := range []Trade{
248			{TradeID: 2, OrderID: aBuy, Symbol: "A", Side: Sell, Price: 10, Qty: 2},
249			{TradeID: 3, OrderID: aSell, Symbol: "A", Side: Buy, Price: 10, Qty: 2},
250		} {
251			rec := recs[recsBefore+i]
252			if rec.Kind != RecordRejected || rec.TradeID != tr.TradeID || rec.Side != tr.Side {
253				t.Fatalf("第 %d 条方向不一致拒绝记录必须保留: %+v", i+1, rec)
254			}
255		}
256	}
257	
258	// TestFillSellMismatchKeepsSellableReservation 覆盖已有部分成交的卖单发生
259	// 合约不一致：已入账部分不能回退，尚未成交部分的可卖占用尤其要保留；
260	// 修正后同一编号按实际所得增加现金、减少持仓并释放相应可卖占用。
261	func TestFillSellMismatchKeepsSellableReservation(t *testing.T) {
262		e, _ := NewEngine(500)
263		mustSetMax(t, e, "A", 100)
264		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
265		mustSetMax(t, e, "B", 100)
266		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 11, Price: 7}, 1)
267	
268		b0 := mustBuy(t, e, "A", 10, 10)
269		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b0, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
270			t.Fatal(err)
271		}
272		sid := mustSell(t, e, "A", 8, 8) // 占用 8 可卖，可卖余 2
273		// 先部分成交 3 股 @9：现金 400+27=427，持仓 7，卖单占用余 5。
274		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 9, Qty: 3}); err != nil {
275			t.Fatal(err)
276		}
277		if e.Cash() != 427 || e.Position("A") != 7 || e.Sellable("A") != 2 {
278			t.Fatalf("前置状态错误: cash=%d pos=%d sellable=%d", e.Cash(), e.Position("A"), e.Sellable("A"))
279		}
280	
281		// 部分成交的卖单收到合约 B 的回报：拒绝；B 也有报价、限额与充足现金。
282		recsBefore := len(e.Records())
283		assertFillMismatchRejected(t, e,
284			Trade{TradeID: 3, OrderID: sid, Symbol: "B", Side: Sell, Price: 9, Qty: 2},
285			recsBefore, "合约", "不一致", "B", "A")
286	
287		// 已入账的 3 股不回退，未成交 5 股的可卖占用不释放。
288		if e.Cash() != 427 || e.Position("A") != 7 || e.Sellable("A") != 2 {
289			t.Fatalf("卖单不一致拒绝不得改变资金、持仓与可卖占用: cash=%d pos=%d sellable=%d",
290				e.Cash(), e.Position("A"), e.Sellable("A"))
291		}
292		if o, _ := e.Order(sid); o.Status != StatusPartial || o.Filled != 3 || o.Remaining() != 5 {
293			t.Fatalf("卖单累计成交与剩余占用必须保留: %+v", o)
294		}
295		if e.Position("B") != 0 || e.Sellable("B") != 0 {
296			t.Fatalf("B 合约不得被转而入账: pos=%d sellable=%d", e.Position("B"), e.Sellable("B"))
297		}
298	
299		// 同一编号改回 A 后按普通成交入账：现金 +2×9=18，持仓 -2，释放 2 可卖占用。
300		res, err := e.Fill(Trade{TradeID: 3, OrderID: sid, Symbol: "A", Side: Sell, Price: 9, Qty: 2})
301		if err != nil {
302			t.Fatalf("卖单修正合约后同编号成交应成功: %v", err)
303		}
304		if res.Filled != 5 || res.Remaining != 3 || res.Status != StatusPartial {
305			t.Fatalf("卖单修正后成交结果错误: %+v", res)
306		}
307		if e.Cash() != 445 || e.Position("A") != 5 || e.Sellable("A") != 2 {
308			t.Fatalf("卖单修正后应按实际所得入账并释放占用: cash=%d pos=%d sellable=%d",
309				e.Cash(), e.Position("A"), e.Sellable("A"))
310		}
311		if o, _ := e.Order(sid); o.Filled != 5 || o.Remaining() != 3 {
312			t.Fatalf("卖单应累计成交 5、剩余 3: %+v", o)
313		}
314	
315		// 先前拒绝记录保留，且只新增了一条拒绝与一条成交。
316		recs := e.Records()
317		if len(recs) != recsBefore+2 {
318			t.Fatalf("修正成交后应只比拒绝前多两条记录，实际 %d 条", len(recs)-recsBefore)
319		}
320		if recs[recsBefore].Kind != RecordRejected || recs[recsBefore].TradeID != 3 ||
321			recs[recsBefore].Symbol != "B" {
322			t.Fatalf("先前拒绝记录必须保留: %+v", recs[recsBefore])
323		}
324	}
