14	// setupSoldAgainstHugeLimit 复现题述前置：初始现金 100，报价与持仓限额就绪，
15	// 以价格 1 买入并成交 2 个单位后现金 98、持仓 2；随后直接提交总量 2、
16	// 限价 hugeLimit 的卖单。卖单必须被接受（整笔限价金额 1e19 无法用 int64
17	// 表示也不拒绝），返回正常订单编号，且不预先改变现金与持仓。
18	func setupSoldAgainstHugeLimit(t *testing.T) (e *Engine, bid, sid int64) {
