65	// TestSellNotionalOverflowAcceptedSettlesPerFill 复现题述完整链路：
66	// 整笔限价金额溢出的卖单接受后，实际成交按每笔回报结算——首笔正常入账并成为
67	// 部分成交，剩余继续占用可卖；第二笔同价回报使现金加总溢出时拒绝并返回
68	// ErrInt64Overflow，前一笔成交与剩余卖单全部保留，成交编号不被占用。
69	func TestSellNotionalOverflowAcceptedSettlesPerFill(t *testing.T) {
70		e, _, sid := setupSoldAgainstHugeLimit(t)
71	
72		// 以该限价成交 1 个单位：单笔金额与入账后现金均在 int64 范围内，
73		// 正常增加现金、减少持仓，订单成为部分成交，剩余 1 继续占用可卖数量。
74		res, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: hugeLimit, Qty: 1})
