81		}
82		if e.Position("A") != 1 || e.Sellable("A") != 0 {
83			t.Fatalf("首笔成交后持仓应减少、剩余量继续占用可卖: pos=%d sellable=%d",
84				e.Position("A"), e.Sellable("A"))
85		}
86		if res.Status != StatusPartial || res.Filled != 1 || res.Remaining != 1 || res.Qty != 1 {
87			t.Fatalf("首笔成交结果错误: %+v", res)
88		}
89		if o, _ := e.Order(sid); o.Status != StatusPartial || o.Filled != 1 ||
90			o.Qty != 2 || o.Limit != hugeLimit || o.Remaining() != 1 {
91			t.Fatalf("订单应成为部分成交并保留原总量与限价: %+v", o)
92		}
