94		// 再提交另一个成交编号、同价同量的回报：现金加总 98 + 5e18 + 5e18 超出 int64，
95		// 拒绝这一笔并返回可识别的 ErrInt64Overflow。
96		before := len(e.Records())
97		res2, err := e.Fill(Trade{TradeID: 3, OrderID: sid, Symbol: "A", Side: Sell, Price: hugeLimit, Qty: 1})
98		if !errors.Is(err, ErrInt64Overflow) {
99			t.Fatalf("现金加总溢出必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
100		}
101		if res2 != (FillResult{}) {
102			t.Fatalf("溢出拒绝必须返回零值成交结果，实际 %+v", res2)
103		}
104	
105		// 前一笔成交与剩余卖单都保留：现金、持仓、订单累计成交量与占用均不改变。
106		if e.Cash() != wantCash || e.Position("A") != 1 || e.Sellable("A") != 0 {
107			t.Fatalf("溢出拒绝不得改变现金、持仓与占用: cash=%d pos=%d sellable=%d",
108				e.Cash(), e.Position("A"), e.Sellable("A"))
109		}
110		if o, _ := e.Order(sid); o.Status != StatusPartial || o.Filled != 1 || o.Remaining() != 1 {
111			t.Fatalf("溢出拒绝不得改变订单累计成交量与剩余量: %+v", o)
112		}
