138		if e.Position("A") != 1 || e.Sellable("A") != 1 || e.Cash() != wantCash {
139			t.Fatalf("撤销剩余卖单应只释放可卖占用: pos=%d sellable=%d cash=%d",
140				e.Position("A"), e.Sellable("A"), e.Cash())
