163		}
164	
165		// 只留原有拒绝记录：现金、持仓、订单累计成交量与可卖占用全部不变。
166		if e.Cash() != 98 || e.Position("A") != 2 || e.Sellable("A") != 0 {
167			t.Fatalf("金额越界成交不得改变现金、持仓与占用: cash=%d pos=%d sellable=%d",
168				e.Cash(), e.Position("A"), e.Sellable("A"))
169		}
170		if o, _ := e.Order(sid); o.Status != StatusPending || o.Filled != 0 || o.Remaining() != 2 {
171			t.Fatalf("金额越界成交不得改变订单: %+v", o)
172		}
173		if len(e.Records()) != before+1 || e.Records()[before].Kind != RecordRejected {
174			t.Fatal("金额越界只能追加一条拒绝记录")
175		}
176	
177		// 成交编号未被占用：同编号改报合法回报（2 股 @1，不低于限价不现实——
178		// 限价为 hugeLimit，故改报限价价 1 股两笔），这里以同编号提交合法的 1 股成交。
179		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell,
180			Price: hugeLimit, Qty: 1}); err != nil {
