7	)
8	
9	// 本文件为“部分成交的卖单调高限价后，已入账成交的幂等重放与尚未入账新成交的
10	// 拒绝口径”补充回归保障。给已经部分成交的卖单调高限价后，先前入账的成交价格
11	// 可能低于新限价，但这笔历史成交仍然有效：同一成交编号、完全相同内容的再次提交
12	// 必须原样返回第一次的成交结果（第一次入账时的累计成交量、剩余量与部分成交
13	// 状态），不能因价格低于新限价而拒绝，也不能把订单当前剩余量回填到历史结果；
14	// 现金、持仓、可卖数量、两张订单与记录数量均保持重放前的值，订单查询继续显示
15	// 修改后的总量与限价。
16	//
17	// 尚未入账的新成交则按处理时的有效参数判断：价格低于新限价时整笔拒绝，返回错误
18	// 与零值成交结果，只追加一条说明“成交价格低于当前限价”的拒绝记录并保留本次回报
19	// 的订单编号、成交编号、合约、方向、价格与数量，不扣持仓、不加现金、不释放卖单
20	// 占用；被拒绝不占用成交编号，把价格修正到不低于新限价后沿用同一编号与数量应
21	// 正常入账，先前的拒绝记录保留，新成交只追加对应的成交记录。整个过程不改变
22	// Modify 修改订单与 Fill 逐笔结算的公开行为。
23	
24	// sellRaisedLimitLedger 是关键操作前后必须保持一致的账户快照。
25	type sellRaisedLimitLedger struct {
26		cash     int64
27		position int64
28		sellable int64
29		target   Order
30		other    Order
31		recs     int
32	}
33	
34	func snapshotSellRaisedLimitLedger(t *testing.T, e *Engine, target, other int64) sellRaisedLimitLedger {
35		t.Helper()
36		to, ok1 := e.Order(target)
37		oo, ok2 := e.Order(other)
38		if !ok1 || !ok2 {
39			t.Fatalf("订单快照缺失: target=%v other=%v", ok1, ok2)
40		}
41		return sellRaisedLimitLedger{
42			cash:     e.Cash(),
43			position: e.Position("A"),
44			sellable: e.Sellable("A"),
45			target:   to,
46			other:    oo,
47			recs:     len(e.Records()),
48		}
49	}
50	
51	// setupSellRaisedLimitReplay 准备题述场景（未开日内亏损保护、行情连续）：
52	// 现金 200，先按价格 10 买入 A 合约 10 份（现金 100、持仓 10）；随后接受总量 8、
53	// 限价 8 的目标卖单，再接受一张总量 2 的卖单占用余下可卖数量；目标卖单先以价格 9
54	// 成交 3 份（现金 127、持仓 7，目标订单累计成交 3、剩余 5，两张卖单占满可卖
55	// 数量）；最后把目标卖单改为总量 6、限价 10——已有 3 份成交不重新计价，现金与
56	// 持仓不变，目标订单剩余 3，可卖数量变为 2，另一张卖单仍保留自己的 2 份占用。
57	//
58	// 返回引擎、两张卖单编号与第一次成交（编号 2、价格 9、数量 3）的成交结果。
59	func setupSellRaisedLimitReplay(t *testing.T) (e *Engine, target, other int64, first FillResult) {
60		t.Helper()
61		e, _ = NewEngine(200)
62		mustSetMax(t, e, "A", 100)
63		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
64	
65		// 先买入同一合约 10 份，每份成交价 10：买单按 10×10 占用现金，成交后
66		// 现金 200-100=100、持仓 10，买单全部成交、占用清零。
67		buyID := mustBuy(t, e, "A", 10, 10)
68		if _, err := e.Fill(Trade{TradeID: 1, OrderID: buyID, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
69			t.Fatalf("前置买入成交应成功: %v", err)
70		}
71		if e.Cash() != 100 || e.ReservedCash() != 0 || e.AvailableCash() != 100 || e.Position("A") != 10 {
72			t.Fatalf("买入成交后账务错误: cash=%d reserved=%d available=%d pos=%d",
73				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
74		}
75	
76		// 接受总量 8、限价 8 的目标卖单；再让另一张卖单占用余下 2 份可卖数量。
77		target = mustSell(t, e, "A", 8, 8)
78		other = mustSell(t, e, "A", 2, 8)
79		if e.Sellable("A") != 0 {
80			t.Fatalf("两张卖单应占满可卖数量，实际可卖 %d", e.Sellable("A"))
81		}
82	
83		// 目标卖单先以价格 9 成交 3 份：现金 100+27=127，持仓 10-3=7，
84		// 目标订单累计成交 3、剩余 5、部分成交。
85		firstTrade := Trade{TradeID: 2, OrderID: target, Symbol: "A", Side: Sell, Price: 9, Qty: 3}
86		first, err := e.Fill(firstTrade)
87		if err != nil {
88			t.Fatalf("目标卖单首次部分成交应成功: %v", err)
89		}
90		if first.TradeID != 2 || first.OrderID != target || first.Price != 9 || first.Qty != 3 ||
91			first.Filled != 3 || first.Remaining != 5 || first.Status != StatusPartial {
92			t.Fatalf("第一次成交结果错误: %+v", first)
93		}
94		if e.Cash() != 127 || e.Position("A") != 7 || e.Sellable("A") != 0 {
95			t.Fatalf("首次卖出成交后账务错误: cash=%d pos=%d sellable=%d",
96				e.Cash(), e.Position("A"), e.Sellable("A"))
97		}
98		if o, _ := e.Order(target); o.Qty != 8 || o.Limit != 8 || o.Filled != 3 ||
99			o.Status != StatusPartial || o.Remaining() != 5 {
100			t.Fatalf("目标订单首次成交后状态错误: %+v", o)
101		}
102	
103		// 把目标卖单改为总量 6、限价 10：已有 3 份成交不重新计价，现金、持仓不变；
104		// 未成交占用由 5 份替换为 3 份，另一张卖单的 2 份占用保留，可卖数量变为 2。
105		mustModify(t, e, target, 6, 10)
106		if e.Cash() != 127 || e.Position("A") != 7 || e.Sellable("A") != 2 {
107			t.Fatalf("修改后账务错误: cash=%d pos=%d sellable=%d",
108				e.Cash(), e.Position("A"), e.Sellable("A"))
109		}
110		to, _ := e.Order(target)
111		if to.Qty != 6 || to.Limit != 10 || to.Filled != 3 ||
112			to.Status != StatusPartial || to.Remaining() != 3 {
113			t.Fatalf("目标订单修改后应为总量 6、限价 10、累计成交 3、剩余 3: %+v", to)
114		}
115		if o, _ := e.Order(other); o.Qty != 2 || o.Limit != 8 || o.Filled != 0 ||
116			o.Status != StatusPending || o.Remaining() != 2 {
117			t.Fatalf("另一张卖单必须保留自己的 2 份占用且不受修改影响: %+v", o)
118		}
119		return e, target, other, first
120	}
121	
122	// TestSellRaisedLimitHistoricalFillReplayRegression 覆盖题述核心：调高部分成交卖单的
123	// 限价后，以原成交编号及完全相同内容再次提交先前那笔价格 9、数量 3 的成交，仍须
124	// 成功返回第一次的成交结果（累计成交 3、剩余 5、部分成交）——不能因价格 9 低于
125	// 新限价 10 而拒绝，也不能把当前剩余 3 回填为历史结果的剩余量；账户现金、持仓、
126	// 可卖数量、两张订单与记录数量均保持重放前的值，订单查询继续显示修改后的总量 6
127	// 与限价 10。
128	func TestSellRaisedLimitHistoricalFillReplayRegression(t *testing.T) {
129		e, target, other, first := setupSellRaisedLimitReplay(t)
130		firstTrade := Trade{TradeID: 2, OrderID: target, Symbol: "A", Side: Sell, Price: 9, Qty: 3}
131	
132		before := snapshotSellRaisedLimitLedger(t, e, target, other)
133		if before.recs != 6 {
134			t.Fatalf("重放前应有 6 条记录（接受买单、成交买单、接受卖单×2、成交卖单、修改），实际 %d",
135				before.recs)
136		}
137		recordsBefore := e.Records()
138	
139		// 再次提交先前那笔成交：原成交编号、完全相同的内容。即使价格 9 低于新限价 10，
140		// 也必须走幂等重放，返回第一次的成交结果而不是按新限价拒绝。
141		replay, err := e.Fill(firstTrade)
142		if err != nil {
143			t.Fatalf("已入账成交以相同内容重放不应报错（即使价格低于新限价）: %v", err)
144		}
145		if replay != first {
146			t.Fatalf("重放必须原样返回第一次成交结果（累计成交 3、剩余 5、部分成交）:\n第一次 %+v\n重放   %+v",
147				first, replay)
148		}
149		if replay.Filled != 3 || replay.Remaining != 5 || replay.Status != StatusPartial {
150			t.Fatalf("重放结果必须保留第一次入账时点的累计 3、剩余 5、部分成交，不得回填当前剩余 3: %+v",
151				replay)
152		}
153	
154		// 现金、持仓、可卖数量、两张订单和记录数量均保持重放前的值。
155		after := snapshotSellRaisedLimitLedger(t, e, target, other)
156		if after != before {
157			t.Fatalf("幂等重放不得改变任何账户状态:\n之前 %+v\n之后 %+v", before, after)
158		}
159		recs := e.Records()
160		for i, want := range recordsBefore {
161			if !reflect.DeepEqual(recs[i], want) {
162				t.Fatalf("第 %d 条原有记录被重放改写:\nwant %+v\ngot  %+v", i, want, recs[i])
163			}
164		}
165	
166		// 订单查询继续显示修改后的总量 6 与限价 10，历史结果不影响订单现状。
167		to, _ := e.Order(target)
168		if to.Qty != 6 || to.Limit != 10 || to.Filled != 3 || to.Remaining() != 3 ||
169			to.Status != StatusPartial {
170			t.Fatalf("重放后订单查询仍须显示修改后的总量 6、限价 10、剩余 3: %+v", to)
171		}
172	}
173	
174	// TestSellRaisedLimitNewFillRejectedThenCorrectedRegression 覆盖题述后半段：用一个
175	// 尚未成功入账的成交编号提交价格 9（低于新限价 10）、数量 2 的新成交，应整笔
176	// 拒绝（错误与零值结果，只追加一条说明价格低于当前限价的拒绝记录，保留本次回报
177	// 全部字段），不扣持仓、不加现金、不释放卖单占用；把价格修正为 10 后沿用刚被
178	// 拒绝的编号与数量应正常入账：现金 147、持仓 5，目标订单累计成交 5、剩余 1、
179	// 仍为部分成交，可卖数量仍为 2，另一张卖单不受影响。先前的拒绝记录保留，新入账
180	// 只追加对应的成交记录。
181	func TestSellRaisedLimitNewFillRejectedThenCorrectedRegression(t *testing.T) {
182		e, target, other, first := setupSellRaisedLimitReplay(t)
183	
184		// 先重放一次历史成交，确认它不会占用或影响随后的新成交（重放不留记录）。
185		firstTrade := Trade{TradeID: 2, OrderID: target, Symbol: "A", Side: Sell, Price: 9, Qty: 3}
186		if replay, err := e.Fill(firstTrade); err != nil || replay != first {
187			t.Fatalf("前置：历史成交重放应返回第一次结果: replay=%+v err=%v", replay, err)
188		}
189	
190		before := snapshotSellRaisedLimitLedger(t, e, target, other)
191		if before.cash != 127 || before.position != 7 || before.sellable != 2 {
192			t.Fatalf("前置账务应为现金 127、持仓 7、可卖 2: %+v", before)
193		}
194	
195		// 用一个尚未成功入账的成交编号提交价格 9、数量 2 的新成交：9 < 新限价 10，
196		// 必须整笔拒绝。
197		rejected := Trade{TradeID: 3, OrderID: target, Symbol: "A", Side: Sell, Price: 9, Qty: 2}
198		res, err := e.Fill(rejected)
199		if err == nil {
200			t.Fatal("成交价 9 低于当前限价 10 必须报错")
201		}
202		if !strings.Contains(err.Error(), "成交 3 被拒绝") ||
203			!strings.Contains(err.Error(), "卖出成交价 9 低于限价 10") {
204			t.Fatalf("错误应说明成交价格低于当前限价: %q", err.Error())
205		}
206		if res != (FillResult{}) {
207			t.Fatalf("被拒绝成交必须返回零值成交结果，实际 %+v", res)
208		}
209	
210		// 只追加一条拒绝记录，并保留本次回报的订单编号、成交编号、合约、方向、
211		// 价格与数量；原因明确指出成交价 9 低于当前限价 10。
212		recs := e.Records()
213		if len(recs) != before.recs+1 {
214			t.Fatalf("拒绝只能新增一条记录，实际新增 %d 条", len(recs)-before.recs)
215		}
216		rj := recs[len(recs)-1]
217		if rj.Kind != RecordRejected {
218			t.Fatalf("新增记录必须是拒绝记录: %+v", rj)
219		}
220		if rj.OrderID != target || rj.TradeID != 3 || rj.Symbol != "A" ||
221			rj.Side != Sell || rj.TradePrice != 9 || rj.Qty != 2 {
222			t.Fatalf("拒绝记录必须保留本次回报的订单/成交编号、合约、方向、价格、数量: %+v", rj)
223		}
224		if rj.Filled != 0 || rj.Remaining != 0 {
225			t.Fatalf("拒绝记录不得携带任何成交量: %+v", rj)
226		}
227		if !strings.Contains(rj.Reason, "卖出成交价 9 低于限价 10") {
228			t.Fatalf("拒绝原因须说明成交价格低于当前限价: %q", rj.Reason)
229		}
230	
231		// 不扣减持仓、不增加现金、不释放卖单占用：现金 127、持仓 7、可卖 2 全部保持。
232		after := snapshotSellRaisedLimitLedger(t, e, target, other)
233		if after.cash != before.cash || after.position != before.position ||
234			after.sellable != before.sellable {
235			t.Fatalf("拒绝不得改变现金、持仓或可卖数量:\n之前 %+v\n之后 %+v", before, after)
236		}
237		if !reflect.DeepEqual(after.target, before.target) ||
238			!reflect.DeepEqual(after.other, before.other) {
239			t.Fatalf("拒绝不得改变两张订单:\n之前 target=%+v other=%+v\n之后 target=%+v other=%+v",
240				before.target, before.other, after.target, after.other)
241		}
242	
243		// 把回报价格修正为 10，沿用刚被拒绝的编号 3 和数量 2：被拒绝不占用编号，
244		// 应正常入账。
245		corrected := Trade{TradeID: 3, OrderID: target, Symbol: "A", Side: Sell, Price: 10, Qty: 2}
246		res, err = e.Fill(corrected)
247		if err != nil {
248			t.Fatalf("修正价格到 10 后沿用编号 3 应正常入账: %v", err)
249		}
250		if res.TradeID != 3 || res.OrderID != target || res.Price != 10 || res.Qty != 2 ||
251			res.Filled != 5 || res.Remaining != 1 || res.Status != StatusPartial {
252			t.Fatalf("修正后成交结果应为累计 5、剩余 1、部分成交: %+v", res)
253		}
254	
255		// 现金 127+20=147，持仓 7-2=5；目标订单累计成交 5、剩余 1；可卖数量仍为 2
256		// （目标剩余 1 + 另一张卖单 2 = 3 份占用，持仓 5，可卖 5-3=2）。
257		if e.Cash() != 147 || e.Position("A") != 5 || e.Sellable("A") != 2 {
258			t.Fatalf("修正成交入账后账务错误: cash=%d pos=%d sellable=%d（应为 147/5/2）",
259				e.Cash(), e.Position("A"), e.Sellable("A"))
260		}
261		if to, _ := e.Order(target); to.Qty != 6 || to.Limit != 10 || to.Filled != 5 ||
262			to.Status != StatusPartial || to.Remaining() != 1 {
263			t.Fatalf("目标订单应累计成交 5、剩余 1、仍为部分成交，总量 6 限价 10 不变: %+v", to)
264		}
265		if oo, _ := e.Order(other); oo.Qty != 2 || oo.Limit != 8 || oo.Filled != 0 ||
266			oo.Status != StatusPending || oo.Remaining() != 2 {
267			t.Fatalf("另一张卖单必须始终保留自己的 2 份占用: %+v", oo)
268		}
269	
270		// 先前的拒绝记录保留，新入账只在其后追加一条成交记录。
271		recs = e.Records()
272		if len(recs) != before.recs+2 {
273			t.Fatalf("修正成交后应只比重放前多两条记录（拒绝+成交），实际 %d 条",
274				len(recs)-before.recs)
275		}
276		if !reflect.DeepEqual(recs[before.recs], rj) {
277			t.Fatalf("先前的拒绝记录必须原样保留:\nwant %+v\ngot  %+v", rj, recs[before.recs])
278		}
279		fr := recs[len(recs)-1]
280		if fr.Kind != RecordFilled || fr.OrderID != target || fr.TradeID != 3 ||
281			fr.Symbol != "A" || fr.Side != Sell || fr.TradePrice != 10 || fr.Qty != 2 ||
282			fr.Filled != 5 || fr.Remaining != 1 {
283			t.Fatalf("新成交记录错误: %+v", fr)
284		}
285	}
