399	func TestLowerMaxPositionCancelsLastBuys(t *testing.T) {
400		e, _ := NewEngine(1000)
401		mustSetMax(t, e, "A", 10)
402		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
403	
404		b1 := mustBuy(t, e, "A", 3, 10) // 最早接受，占用 30
405		b2 := mustBuy(t, e, "A", 3, 10)
406		b3 := mustBuy(t, e, "A", 3, 10) // 最后接受，持仓占用共 9
407	
408		// b1 部分成交 2 股 @9：现金 -18，持仓 2，买单剩余额度 7。
409		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b1, Symbol: "A", Side: Buy, Price: 9, Qty: 2}); err != nil {
410			t.Fatal(err)
411		}
412		// 此时 持仓 2 + 买单剩余 7 = 9。下调限额到 5：
413		// 先取消 b3（剩余 3）→ 2+4=6 仍超；再取消 b2（剩余 3）→ 2+1 满足。
414		canceled := mustSetMax(t, e, "A", 5)
415		if len(canceled) != 2 || canceled[0] != b3 || canceled[1] != b2 {
416			t.Fatalf("应按最后接受顺序撤销 b3,b2，实际 %v", canceled)
417		}
418		if e.ReservedCash() != 10 { // b1 剩余 1 股 × 10
419			t.Fatalf("撤单释放现金错误: reserved=%d", e.ReservedCash())
420		}
421		if e.Cash() != 1000-18 {
422			t.Fatalf("撤单不得触动已成交金额: cash=%d", e.Cash())
423		}
424		o1, _ := e.Order(b1)
425		if o1.Status != StatusPartial {
426			t.Fatal("b1 应保持部分成交")
427		}
428	
429		// 再下调到 1：持仓 2 已超限，撤掉全部未成交买单（b1 剩余 1）。
430		canceled = mustSetMax(t, e, "A", 1)
431		if len(canceled) != 1 || canceled[0] != b1 {
432			t.Fatalf("持仓超限时应撤销 b1，实际 %v", canceled)
433		}
434		if e.ReservedCash() != 0 || e.Position("A") != 2 {
435			t.Fatalf("撤销全部买单后 reserved=0、持仓保留: reserved=%d pos=%d", e.ReservedCash(), e.Position("A"))
436		}
437		// 持仓超限：后续买单拒绝。
438		if _, err := e.Buy("A", 1, 10); err == nil {
439			t.Fatal("持仓超限时新买单必须拒绝")
440		}
441		// 仍允许卖出，不自动平仓。
442		sid := mustSell(t, e, "A", 2, 10)
443		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 2}); err != nil {
444			t.Fatal(err)
445		}
446		if e.Position("A") != 0 || e.Cash() != 1000-18+20 {
447			t.Fatalf("卖出后状态错误: pos=%d cash=%d", e.Position("A"), e.Cash())
448		}
449	
450		// 负限额报错。
451		if _, err := e.SetMaxPosition("A", -1); err == nil {
452			t.Fatal("负最大持仓量必须报错")
453		}
454	}
