456	func TestRecordsSnapshotsAndImmutability(t *testing.T) {
457		e, _ := NewEngine(1000)
458	
459		// 无报价、无限额时的拒绝记录：快照明确为空。
460		_, err := e.Buy("X", 1, 10)
461		expectErr(t, err, "尚未设置最大持仓量")
462		recs := e.Records()
463		if len(recs) != 1 || recs[0].Kind != RecordRejected || recs[0].QuoteValid || recs[0].MaxPositionValid {
464			t.Fatalf("拒绝记录快照应为空: %+v", recs)
465		}
466		if recs[0].Reason == "" {
467			t.Fatal("拒绝记录必须包含具体原因")
468		}
469	
470		mustSetMax(t, e, "A", 10)
471		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 100, Price: 10}, 1)
472		id := mustBuy(t, e, "A", 4, 10)
473	
474		// 接受记录快照：报价 seq1 与限额 10。
475		rec := e.Records()[1]
476		if rec.Kind != RecordAccepted || !rec.QuoteValid || rec.QuoteSeq != 1 || rec.QuoteMoment != 100 ||
477			rec.QuotePrice != 10 || !rec.MaxPositionValid || rec.MaxPosition != 10 {
478			t.Fatalf("接受记录快照错误: %+v", rec)
479		}
480	
481		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 9, Qty: 2}); err != nil {
482			t.Fatal(err)
483		}
484		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 200, Price: 20}, 1)
485		mustSetMax(t, e, "A", 99)
486	
487		// 后续报价与限额变化不能改写历史记录，且成交金额不重算。
488		rec = e.Records()[2]
489		if rec.Kind != RecordFilled || rec.QuoteSeq != 1 || rec.QuotePrice != 10 || rec.MaxPosition != 10 {
490			t.Fatalf("成交记录被后续变化改写: %+v", rec)
491		}
492		if e.Cash() != 1000-18 {
493			t.Fatalf("报价变化不得重算已成交金额: cash=%d", e.Cash())
494		}
495	
496		// 限额下调触发的撤销记录带原因与当时快照（seq2, 限额99）。
497		canceled := mustSetMax(t, e, "A", 1) // 持仓 2 超限，撤销剩余买单 2
498		if len(canceled) != 1 {
499			t.Fatalf("应撤销 1 单，实际 %v", canceled)
500		}
501		rec = e.Records()[len(e.Records())-1]
502		if rec.Kind != RecordCanceled || rec.Reason == "" || !rec.QuoteValid ||
503			rec.QuoteSeq != 2 || rec.QuotePrice != 20 || rec.MaxPosition != 1 {
504			t.Fatalf("限额撤销记录快照/原因错误: %+v", rec)
505		}
506		if rec.Remaining != 2 || rec.Filled != 2 {
507			t.Fatalf("撤销记录应区分已成交 2 与剩余 2: %+v", rec)
508		}
509	
510		// 状态枚举中文可辨识。
511		if StatusPending.String() != "待成交" || StatusPartial.String() != "部分成交" ||
512			StatusFilled.String() != "全部成交" || StatusCanceled.String() != "已撤销" {
513			t.Fatal("订单状态文案错误")
514		}
515	}
